// Fibonacci - TypeScript Implementation
// Phase 2: Recursion, Iteration, Memoization

function fibRecursive(n: number): number {
  if (n <= 1) {
    return n;
  }
  return fibRecursive(n - 1) + fibRecursive(n - 2);
}

function fibIterative(n: number): number {
  if (n <= 1) {
    return n;
  }

  let a = 0;
  let b = 1;

  for (let i = 2; i <= n; i++) {
    const temp = a + b;
    a = b;
    b = temp;
  }

  return b;
}

function fibMemoized(n: number, memo: Map<number, number> = new Map()): number {
  if (memo.has(n)) {
    return memo.get(n)!;
  }

  let result: number;
  if (n <= 1) {
    result = n;
  } else {
    result = fibMemoized(n - 1, memo) + fibMemoized(n - 2, memo);
  }

  memo.set(n, result);
  return result;
}

function main(): void {
  const n = 10;

  // Recursive
  let start = performance.now();
  const resultRecursive = fibRecursive(n);
  const timeRecursive = performance.now() - start;

  // Iterative
  start = performance.now();
  const resultIterative = fibIterative(n);
  const timeIterative = performance.now() - start;

  // Memoized
  start = performance.now();
  const resultMemoized = fibMemoized(n);
  const timeMemoized = performance.now() - start;

  console.log(`fib(${n}) = ${resultRecursive} (recursive: ${timeRecursive.toFixed(3)}ms)`);
  console.log(`fib(${n}) = ${resultIterative} (iterative: ${timeIterative.toFixed(3)}ms)`);
  console.log(`fib(${n}) = ${resultMemoized} (memoized: ${timeMemoized.toFixed(3)}ms)`);
}

main();

