/**
 * Fibonacci - Java Implementation
 * Phase 2: Recursion, Iteration, Memoization
 */

import java.util.HashMap;
import java.util.Map;

public class Fibonacci {

    public static long fibRecursive(long n) {
        if (n <= 1) {
            return n;
        }
        return fibRecursive(n - 1) + fibRecursive(n - 2);
    }

    public static long fibIterative(long n) {
        if (n <= 1) {
            return n;
        }

        long a = 0;
        long b = 1;

        for (long i = 2; i <= n; i++) {
            long temp = a + b;
            a = b;
            b = temp;
        }

        return b;
    }

    public static long fibMemoized(long n, Map<Long, Long> memo) {
        if (memo.containsKey(n)) {
            return memo.get(n);
        }

        long result;
        if (n <= 1) {
            result = n;
        } else {
            result = fibMemoized(n - 1, memo) + fibMemoized(n - 2, memo);
        }

        memo.put(n, result);
        return result;
    }

    public static void main(String[] args) {
        long n = 10;

        // Recursive
        long startTime = System.nanoTime();
        long resultRecursive = fibRecursive(n);
        long timeRecursive = (System.nanoTime() - startTime) / 1_000_000;

        // Iterative
        startTime = System.nanoTime();
        long resultIterative = fibIterative(n);
        long timeIterative = (System.nanoTime() - startTime) / 1_000_000;

        // Memoized
        startTime = System.nanoTime();
        Map<Long, Long> memo = new HashMap<>();
        long resultMemoized = fibMemoized(n, memo);
        long timeMemoized = (System.nanoTime() - startTime) / 1_000_000;

        System.out.printf("fib(%d) = %d (recursive: %d.000ms)%n", n, resultRecursive, timeRecursive);
        System.out.printf("fib(%d) = %d (iterative: %d.000ms)%n", n, resultIterative, timeIterative);
        System.out.printf("fib(%d) = %d (memoized: %d.000ms)%n", n, resultMemoized, timeMemoized);
    }
}

