fun fibRecursive(n: Int): Int {
    if (n <= 1) {
        return n
    }
    return fibRecursive(n - 1) + fibRecursive(n - 2)
}

fun fibIterative(n: Int): Int {
    if (n <= 1) {
        return n
    }

    var a = 0
    var b = 1

    for (i in 2..n) {
        val temp = a + b
        a = b
        b = temp
    }

    return b
}

fun fibMemoized(n: Int, memo: MutableMap<Int, Int> = mutableMapOf()): Int {
    if (memo.containsKey(n)) {
        return memo[n]!!
    }

    val result = if (n <= 1) {
        n
    } else {
        fibMemoized(n - 1, memo) + fibMemoized(n - 2, memo)
    }

    memo[n] = result
    return result
}

