// String Operations - Rust Implementation
// Phase 3: Concatenation, Slicing, Substring Search, Case Conversion

fn string_concatenation(str1: &str, str2: &str) -> String {
    format!("{}{}", str1, str2)
}

fn string_slicing(text: &str, start: usize, end: usize) -> &str {
    if end > text.len() {
        return text;
    }
    &text[start..end]
}

fn string_search(text: &str, substring: &str) -> i32 {
    match text.find(substring) {
        Some(pos) => pos as i32,
        None => -1,
    }
}

fn string_upper(text: &str) -> String {
    text.to_uppercase()
}

fn string_lower(text: &str) -> String {
    text.to_lowercase()
}

fn string_split(text: &str, delimiter: &str) -> Vec<&str> {
    text.split(delimiter).collect()
}

fn string_join(words: &[&str], delimiter: &str) -> String {
    words.join(delimiter)
}

fn string_replace(text: &str, old: &str, new: &str) -> String {
    text.replace(old, new)
}

fn string_trim(text: &str) -> &str {
    text.trim()
}

fn string_reverse(text: &str) -> String {
    text.chars().rev().collect()
}

fn main() {
    // Concatenation
    let result = string_concatenation("Hello, ", "World!");
    println!("Concatenation: {}", result);

    // Slicing
    let result = string_slicing("Hello, World!", 0, 5);
    println!("Slicing [0:5]: {}", result);

    // Search
    let idx = string_search("Hello, World!", "World");
    println!("Search index: {}", idx);

    // Case conversion
    let upper = string_upper("hello");
    let lower = string_lower("WORLD");
    println!("Upper: {}, Lower: {}", upper, lower);

    // Split and Join
    let words: Vec<&str> = string_split("apple,banana,orange", ",");
    let joined = string_join(&words, "-");
    println!("Split and join: {}", joined);

    // Replace
    let result = string_replace("hello world", "world", "freelang");
    println!("Replace: {}", result);

    // Trim
    let result = string_trim("  hello  ");
    println!("Trim: '{}'", result);

    // Reverse
    let result = string_reverse("hello");
    println!("Reverse: {}", result);
}

