/**
 * String Operations - Java Implementation
 * Phase 3: Concatenation, Slicing, Substring Search, Case Conversion
 */

public class StringOps {

    public static String stringConcatenation(String str1, String str2) {
        return str1 + str2;
    }

    public static String stringSlicing(String text, int start, int end) {
        if (end > text.length()) {
            return text;
        }
        return text.substring(start, end);
    }

    public static int stringSearch(String text, String substring) {
        int idx = text.indexOf(substring);
        return idx;
    }

    public static String stringUpper(String text) {
        return text.toUpperCase();
    }

    public static String stringLower(String text) {
        return text.toLowerCase();
    }

    public static String[] stringSplit(String text, String delimiter) {
        return text.split(delimiter);
    }

    public static String stringJoin(String[] words, String delimiter) {
        return String.join(delimiter, words);
    }

    public static String stringReplace(String text, String old, String newStr) {
        return text.replaceAll(old, newStr);
    }

    public static String stringTrim(String text) {
        return text.trim();
    }

    public static String stringReverse(String text) {
        return new StringBuilder(text).reverse().toString();
    }

    public static void main(String[] args) {
        // Concatenation
        String result = stringConcatenation("Hello, ", "World!");
        System.out.println("Concatenation: " + result);

        // Slicing
        result = stringSlicing("Hello, World!", 0, 5);
        System.out.println("Slicing [0:5]: " + result);

        // Search
        int idx = stringSearch("Hello, World!", "World");
        System.out.println("Search index: " + idx);

        // Case conversion
        String upper = stringUpper("hello");
        String lower = stringLower("WORLD");
        System.out.println("Upper: " + upper + ", Lower: " + lower);

        // Split and Join
        String[] words = stringSplit("apple,banana,orange", ",");
        String joined = stringJoin(words, "-");
        System.out.println("Split and join: " + joined);

        // Replace
        result = stringReplace("hello world", "world", "freelang");
        System.out.println("Replace: " + result);

        // Trim
        result = stringTrim("  hello  ");
        System.out.println("Trim: '" + result + "'");

        // Reverse
        result = stringReverse("hello");
        System.out.println("Reverse: " + result);
    }
}

