// Array Operations - Rust Implementation
// Phase 4: Creation, Iteration, Map, Filter, Reduce

fn array_create(size: usize, value: i32) -> Vec<i32> {
    vec![value; size]
}

fn array_sum(arr: &[i32]) -> i32 {
    arr.iter().sum()
}

fn array_map(arr: &[i32], multiplier: i32) -> Vec<i32> {
    arr.iter().map(|x| x * multiplier).collect()
}

fn array_filter(arr: &[i32], threshold: i32) -> Vec<i32> {
    arr.iter().filter(|&&x| x > threshold).map(|&x| x).collect()
}

fn array_reduce(arr: &[i32]) -> i32 {
    arr.iter().fold(0, |acc, x| acc + x)
}

fn array_reverse(arr: &[i32]) -> Vec<i32> {
    arr.iter().rev().map(|&x| x).collect()
}

fn array_find(arr: &[i32], value: i32) -> i32 {
    match arr.iter().position(|&x| x == value) {
        Some(pos) => pos as i32,
        None => -1,
    }
}

fn array_contains(arr: &[i32], value: i32) -> bool {
    arr.contains(&value)
}

fn array_length(arr: &[i32]) -> usize {
    arr.len()
}

fn array_join(arr: &[i32], separator: &str) -> String {
    arr.iter()
        .map(|x| x.to_string())
        .collect::<Vec<_>>()
        .join(separator)
}

fn main() {
    // Create array
    let arr = array_create(5, 1);
    println!("Created array: {:?}", arr);

    // Sum
    let total = array_sum(&arr);
    println!("Sum: {}", total);

    // Map
    let mapped = array_map(&arr, 2);
    println!("Mapped (x2): {:?}", mapped);

    // Filter
    let arr2 = vec![1, 2, 3, 4, 5];
    let filtered = array_filter(&arr2, 2);
    println!("Filtered (>2): {:?}", filtered);

    // Reduce
    let total = array_reduce(&arr2);
    println!("Reduce (sum): {}", total);

    // Reverse
    let reversed_arr = array_reverse(&arr2);
    println!("Reversed: {:?}", reversed_arr);

    // Find
    let idx = array_find(&arr2, 3);
    println!("Find index of 3: {}", idx);

    // Contains
    let exists = array_contains(&arr2, 4);
    println!("Contains 4: {}", exists);

    // Length
    let length = array_length(&arr2);
    println!("Length: {}", length);

    // Join
    let joined = array_join(&arr2, ",");
    println!("Joined: {}", joined);
}

