use std::f64;

struct Calculator {
    history: Vec<String>,
    last_result: f64,
}

impl Calculator {
    fn new() -> Calculator {
        Calculator {
            history: Vec::new(),
            last_result: 0.0,
        }
    }

    fn add(&mut self, a: f64, b: f64) -> f64 {
        let result = a + b;
        self.history.push(format!("{} + {} = {}", a, b, result));
        self.last_result = result;
        result
    }

    fn subtract(&mut self, a: f64, b: f64) -> f64 {
        let result = a - b;
        self.history.push(format!("{} - {} = {}", a, b, result));
        self.last_result = result;
        result
    }

    fn multiply(&mut self, a: f64, b: f64) -> f64 {
        let result = a * b;
        self.history.push(format!("{} * {} = {}", a, b, result));
        self.last_result = result;
        result
    }

    fn divide(&mut self, a: f64, b: f64) -> Result<f64, String> {
        if b == 0.0 {
            return Err("Division by zero".to_string());
        }
        let result = a / b;
        self.history.push(format!("{} / {} = {}", a, b, result));
        self.last_result = result;
        Ok(result)
    }

    fn power(&mut self, base: f64, exponent: f64) -> f64 {
        let result = base.powf(exponent);
        self.history.push(format!("{} ^ {} = {}", base, exponent, result));
        self.last_result = result;
        result
    }

    fn square_root(&mut self, value: f64) -> Result<f64, String> {
        if value < 0.0 {
            return Err("Cannot take square root of negative number".to_string());
        }
        let result = value.sqrt();
        self.history.push(format!("sqrt({}) = {}", value, result));
        self.last_result = result;
        Ok(result)
    }

    fn get_history(&self) -> &Vec<String> {
        &self.history
    }

    fn clear_history(&mut self) {
        self.history.clear();
    }

    fn get_last_result(&self) -> f64 {
        self.last_result
    }
}

fn main() {
    let mut calc = Calculator::new();

    // Basic operations
    println!("=== Calculator Demo ===");
    println!("5 + 3 = {}", calc.add(5.0, 3.0));
    println!("10 - 4 = {}", calc.subtract(10.0, 4.0));
    println!("6 * 7 = {}", calc.multiply(6.0, 7.0));
    match calc.divide(20.0, 4.0) {
        Ok(result) => println!("20 / 4 = {}", result),
        Err(e) => println!("Error: {}", e),
    }
    println!("2 ^ 8 = {}", calc.power(2.0, 8.0));
    match calc.square_root(16.0) {
        Ok(result) => println!("sqrt(16) = {}", result),
        Err(e) => println!("Error: {}", e),
    }

    // History
    println!("\n=== History ===");
    for operation in calc.get_history() {
        println!("{}", operation);
    }

    // Last result
    println!("\nLast result: {}", calc.get_last_result());
}

