class Calculator {
  private history: string[] = [];
  private lastResult: number = 0;

  add(a: number, b: number): number {
    const result = a + b;
    this.history.push(`${a} + ${b} = ${result}`);
    this.lastResult = result;
    return result;
  }

  subtract(a: number, b: number): number {
    const result = a - b;
    this.history.push(`${a} - ${b} = ${result}`);
    this.lastResult = result;
    return result;
  }

  multiply(a: number, b: number): number {
    const result = a * b;
    this.history.push(`${a} * ${b} = ${result}`);
    this.lastResult = result;
    return result;
  }

  divide(a: number, b: number): number | null {
    if (b === 0) {
      console.error("Division by zero");
      return null;
    }
    const result = a / b;
    this.history.push(`${a} / ${b} = ${result}`);
    this.lastResult = result;
    return result;
  }

  power(base: number, exponent: number): number {
    const result = Math.pow(base, exponent);
    this.history.push(`${base} ^ ${exponent} = ${result}`);
    this.lastResult = result;
    return result;
  }

  squareRoot(value: number): number | null {
    if (value < 0) {
      console.error("Cannot take square root of negative number");
      return null;
    }
    const result = Math.sqrt(value);
    this.history.push(`sqrt(${value}) = ${result}`);
    this.lastResult = result;
    return result;
  }

  getHistory(): string[] {
    return this.history;
  }

  clearHistory(): void {
    this.history = [];
  }

  getLastResult(): number {
    return this.lastResult;
  }
}

