package main

import (
	"fmt"
	"os/exec"
	"strings"
)

// ============================================================================
// Language Adapters
// ============================================================================
// Adapters for FreeLang, Go, C, WASM, FV-Julia package managers
// ============================================================================

// Adapter interface for language package managers
type Adapter interface {
	Install(name, version string) error
	Remove(name string) error
	ListInstalled() ([]Package, error)
	GetVersion(name string) (string, error)
}

// NewAdapter creates adapter for language
func NewAdapter(lang string) Adapter {
	switch lang {
	case "go":
		return NewGoAdapter()
	case "c":
		return NewCAdapter()
	case "freelang":
		return NewFreeLangAdapter()
	case "wasm":
		return NewWasmAdapter()
	case "fv-julia":
		return NewFVJuliaAdapter()
	default:
		return nil
	}
}

// ============================================================================
// Go Adapter (Go Modules)
// ============================================================================

// GoAdapter adapts Go Modules
type GoAdapter struct{}

// NewGoAdapter creates Go adapter
func NewGoAdapter() *GoAdapter {
	return &GoAdapter{}
}

// Install installs Go package
func (ga *GoAdapter) Install(name, version string) error {
	cmd := fmt.Sprintf("go get %s@%s", name, version)
	if version == "latest" {
		cmd = fmt.Sprintf("go get %s", name)
	}

	return runCommand(cmd)
}

// Remove removes Go package
func (ga *GoAdapter) Remove(name string) error {
	cmd := fmt.Sprintf("go get %s@none", name)
	return runCommand(cmd)
}

// ListInstalled lists installed Go packages
func (ga *GoAdapter) ListInstalled() ([]Package, error) {
	output, err := exec.Command("go", "list", "-m", "all").CombinedOutput()
	if err != nil {
		return nil, err
	}

	var packages []Package
	lines := strings.Split(string(output), "\n")

	for _, line := range lines {
		if line == "" {
			continue
		}

		parts := strings.Fields(line)
		if len(parts) >= 2 {
			packages = append(packages, Package{
				Name:     parts[0],
				Version:  parts[1],
				Language: "go",
			})
		}
	}

	return packages, nil
}

// GetVersion gets Go package version
func (ga *GoAdapter) GetVersion(name string) (string, error) {
	// Use go list to get version
	output, err := exec.Command("go", "list", "-m", name).CombinedOutput()
	if err != nil {
		return "", err
	}

	parts := strings.Fields(string(output))
	if len(parts) >= 2 {
		return parts[1], nil
	}

	return "", fmt.Errorf("could not determine version")
}

// ============================================================================
// C Adapter (Conan)
// ============================================================================

// CAdapter adapts C package managers (Conan, vcpkg)
type CAdapter struct{}

// NewCAdapter creates C adapter
func NewCAdapter() *CAdapter {
	return &CAdapter{}
}

// Install installs C package
func (ca *CAdapter) Install(name, version string) error {
	// Try Conan first
	cmd := fmt.Sprintf("conan install --requires=%s/%s", name, version)

	return runCommand(cmd)
}

// Remove removes C package
func (ca *CAdapter) Remove(name string) error {
	// Conan doesn't have uninstall; remove from conanfile.txt
	return nil
}

// ListInstalled lists installed C packages
func (ca *CAdapter) ListInstalled() ([]Package, error) {
	// Read conanfile.txt or conaninfo.txt
	return []Package{}, nil
}

// GetVersion gets C package version
func (ca *CAdapter) GetVersion(name string) (string, error) {
	// Query Conan registry
	return "", nil
}

// ============================================================================
// FreeLang Adapter
// ============================================================================

// FreeLangAdapter adapts FreeLang package manager
type FreeLangAdapter struct{}

// NewFreeLangAdapter creates FreeLang adapter
func NewFreeLangAdapter() *FreeLangAdapter {
	return &FreeLangAdapter{}
}

// Install installs FreeLang package
func (fa *FreeLangAdapter) Install(name, version string) error {
	cmd := fmt.Sprintf("freelang-pkg install %s@%s", name, version)
	if version == "latest" {
		cmd = fmt.Sprintf("freelang-pkg install %s", name)
	}

	return runCommand(cmd)
}

// Remove removes FreeLang package
func (fa *FreeLangAdapter) Remove(name string) error {
	cmd := fmt.Sprintf("freelang-pkg remove %s", name)
	return runCommand(cmd)
}

// ListInstalled lists installed FreeLang packages
func (fa *FreeLangAdapter) ListInstalled() ([]Package, error) {
	output, err := exec.Command("freelang-pkg", "list").CombinedOutput()
	if err != nil {
		return nil, err
	}

	var packages []Package
	lines := strings.Split(string(output), "\n")

	for _, line := range lines {
		if line == "" {
			continue
		}

		parts := strings.Fields(line)
		if len(parts) >= 2 {
			packages = append(packages, Package{
				Name:     parts[0],
				Version:  parts[1],
				Language: "freelang",
			})
		}
	}

	return packages, nil
}

// GetVersion gets FreeLang package version
func (fa *FreeLangAdapter) GetVersion(name string) (string, error) {
	output, err := exec.Command("freelang-pkg", "info", name).CombinedOutput()
	if err != nil {
		return "", err
	}

	// Parse output to find version
	lines := strings.Split(string(output), "\n")
	for _, line := range lines {
		if strings.Contains(line, "Version:") {
			parts := strings.Split(line, ":")
			if len(parts) > 1 {
				return strings.TrimSpace(parts[1]), nil
			}
		}
	}

	return "", fmt.Errorf("could not determine version")
}

// ============================================================================
// WASM Adapter (npm/Cargo)
// ============================================================================

// WasmAdapter adapts WASM package managers
type WasmAdapter struct{}

// NewWasmAdapter creates WASM adapter
func NewWasmAdapter() *WasmAdapter {
	return &WasmAdapter{}
}

// Install installs WASM package
func (wa *WasmAdapter) Install(name, version string) error {
	// Try npm first
	cmd := fmt.Sprintf("npm install %s@%s", name, version)
	if version == "latest" {
		cmd = fmt.Sprintf("npm install %s", name)
	}

	return runCommand(cmd)
}

// Remove removes WASM package
func (wa *WasmAdapter) Remove(name string) error {
	cmd := fmt.Sprintf("npm uninstall %s", name)
	return runCommand(cmd)
}

// ListInstalled lists installed WASM packages
func (wa *WasmAdapter) ListInstalled() ([]Package, error) {
	output, err := exec.Command("npm", "list", "--depth=0").CombinedOutput()
	if err != nil {
		return nil, err
	}

	var packages []Package
	lines := strings.Split(string(output), "\n")

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "+--") || strings.HasPrefix(line, "`--") {
			continue
		}

		// Parse "package@version"
		parts := strings.Split(line, "@")
		if len(parts) >= 2 {
			name := strings.Join(parts[:len(parts)-1], "@")
			version := parts[len(parts)-1]

			packages = append(packages, Package{
				Name:     name,
				Version:  version,
				Language: "wasm",
			})
		}
	}

	return packages, nil
}

// GetVersion gets WASM package version
func (wa *WasmAdapter) GetVersion(name string) (string, error) {
	output, err := exec.Command("npm", "view", name, "version").CombinedOutput()
	if err != nil {
		return "", err
	}

	return strings.TrimSpace(string(output)), nil
}

// ============================================================================
// FV-Julia Adapter
// ============================================================================

// FVJuliaAdapter adapts FV-Julia package manager
type FVJuliaAdapter struct{}

// NewFVJuliaAdapter creates FV-Julia adapter
func NewFVJuliaAdapter() *FVJuliaAdapter {
	return &FVJuliaAdapter{}
}

// Install installs FV-Julia package
func (fa *FVJuliaAdapter) Install(name, version string) error {
	cmd := fmt.Sprintf("julia -e 'using Pkg; Pkg.add(\"%s\", version=\"%s\")'", name, version)
	if version == "latest" {
		cmd = fmt.Sprintf("julia -e 'using Pkg; Pkg.add(\"%s\")'", name)
	}

	return runCommand(cmd)
}

// Remove removes FV-Julia package
func (fa *FVJuliaAdapter) Remove(name string) error {
	cmd := fmt.Sprintf("julia -e 'using Pkg; Pkg.rm(\"%s\")'", name)
	return runCommand(cmd)
}

// ListInstalled lists installed FV-Julia packages
func (fa *FVJuliaAdapter) ListInstalled() ([]Package, error) {
	output, err := exec.Command("julia", "-e", "using Pkg; Pkg.status()").CombinedOutput()
	if err != nil {
		return nil, err
	}

	var packages []Package
	lines := strings.Split(string(output), "\n")

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}

		// Parse "name version"
		parts := strings.Fields(line)
		if len(parts) >= 2 {
			packages = append(packages, Package{
				Name:     parts[0],
				Version:  parts[1],
				Language: "fv-julia",
			})
		}
	}

	return packages, nil
}

// GetVersion gets FV-Julia package version
func (fa *FVJuliaAdapter) GetVersion(name string) (string, error) {
	output, err := exec.Command("julia", "-e", fmt.Sprintf("using Pkg; println(Pkg.status(\"%s\"))", name)).CombinedOutput()
	if err != nil {
		return "", err
	}

	// Parse output
	lines := strings.Split(string(output), "\n")
	for _, line := range lines {
		parts := strings.Fields(line)
		if len(parts) >= 2 {
			return parts[1], nil
		}
	}

	return "", fmt.Errorf("could not determine version")
}

// ============================================================================
// Helper Functions
// ============================================================================

// runCommand runs shell command
func runCommand(cmd string) error {
	parts := strings.Fields(cmd)
	if len(parts) == 0 {
		return fmt.Errorf("empty command")
	}

	execCmd := exec.Command(parts[0], parts[1:]...)
	output, err := execCmd.CombinedOutput()

	if err != nil {
		return fmt.Errorf("command failed: %s\nOutput: %s", cmd, string(output))
	}

	return nil
}

