// ============================================================================
// Adapters for FreeLang, Go, C, WASM, FV-Julia package managers
// ============================================================================

// Adapter interface for language package managers
type Adapter interface {
	Install(name, version string) error
	Remove(name string) error
	ListInstalled() ([]Package, error)
	GetVersion(name string) (string, error)
}

// NewAdapter creates adapter for language
func NewAdapter(lang string) Adapter {
	switch lang {
	case "go":
		return NewGoAdapter()
	case "c":
		return NewCAdapter()
	case "freelang":
		return NewFreeLangAdapter()
	case "wasm":
		return NewWasmAdapter()
	case "fv-julia":
		return NewFVJuliaAdapter()
	default:
		return nil
	}
}

// ============================================================================
// Go Adapter (Go Modules)
// ============================================================================

// GoAdapter adapts Go Modules
type GoAdapter struct{}

// NewGoAdapter creates Go adapter
func NewGoAdapter() *GoAdapter {
	return &GoAdapter{}
}

// Install installs Go package
func (ga *GoAdapter) Install(name, version string) error {
	cmd := fmt.Sprintf("go get %s@%s", name, version)
	if version == "latest" {
		cmd = fmt.Sprintf("go get %s", name)
	}

	return runCommand(cmd)
}

// Remove removes Go package
func (ga *GoAdapter) Remove(name string) error {
	cmd := fmt.Sprintf("go get %s@none", name)
	return runCommand(cmd)
}

// ListInstalled lists installed Go packages
func (ga *GoAdapter) ListInstalled() ([]Package, error) {
	output, err := exec.Command("go", "list", "-m", "all").CombinedOutput()
	if err != nil {
		return nil, err
	}

	var packages []Package
	lines := strings.Split(string(output), "\n")

	for _, line := range lines {
		if line == "" {
			continue
		}

		parts := strings.Fields(line)
		if len(parts) >= 2 {
			packages = append(packages, Package{
				Name:     parts[0],
				Version:  parts[1],
				Language: "go",
			})
		}
	}

	return packages, nil
}

// GetVersion gets Go package version
func (ga *GoAdapter) GetVersion(name string) (string, error) {
	// Use go list to get version
	output, err := exec.Command("go", "list", "-m", name).CombinedOutput()
	if err != nil {
		return "", err
	}

	parts := strings.Fields(string(output))
	if len(parts) >= 2 {
		return parts[1], nil
	}

	return "", fmt.Errorf("could not determine version")
}

