	return runCommand(cmd)
}

// Remove removes Rust package
func (ra *RustAdapter) Remove(name string) error {
	cmd := fmt.Sprintf("cargo remove %s", name)
	return runCommand(cmd)
}

// ListInstalled lists installed Rust packages
func (ra *RustAdapter) ListInstalled() ([]Package, error) {
	output, err := exec.Command("cargo", "tree", "--depth=1").CombinedOutput()
	if err != nil {
		return nil, err
	}

	var packages []Package
	lines := strings.Split(string(output), "\n")

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}

		// Parse "name v0.1.0"
		parts := strings.Fields(line)
		if len(parts) >= 2 {
			packages = append(packages, Package{
				Name:     parts[0],
				Version:  parts[1],
				Language: "rust",
			})
		}
	}

	return packages, nil
}

// GetVersion gets Rust package version
func (ra *RustAdapter) GetVersion(name string) (string, error) {
	output, err := exec.Command("cargo", "search", name, "--limit=1").CombinedOutput()
	if err != nil {
		return "", err
	}

	lines := strings.Split(string(output), "\n")
	for _, line := range lines {
		if strings.Contains(line, "=") {
			parts := strings.Split(line, "=")
			if len(parts) > 1 {
				version := strings.TrimSpace(parts[1])
				// Remove quotes if present
				version = strings.Trim(version, "\"")
				return version, nil
			}
		}
	}

	return "", fmt.Errorf("could not determine version")
}

// ============================================================================
// TypeScript Adapter (npm)
// ============================================================================

// TypeScriptAdapter adapts TypeScript package manager (npm)
type TypeScriptAdapter struct{}

// NewTypeScriptAdapter creates TypeScript adapter
func NewTypeScriptAdapter() *TypeScriptAdapter {
	return &TypeScriptAdapter{}
}

// Install installs TypeScript package
func (ta *TypeScriptAdapter) Install(name, version string) error {
	cmd := fmt.Sprintf("npm install %s@%s", name, version)
	if version == "latest" {
		cmd = fmt.Sprintf("npm install %s", name)
	}

	return runCommand(cmd)
