	if err != nil {
		return "", err
	}

	return strings.TrimSpace(string(output)), nil
}

// ============================================================================
// Java Adapter (Maven)
// ============================================================================

// JavaAdapter adapts Java package manager (Maven)
type JavaAdapter struct{}

// NewJavaAdapter creates Java adapter
func NewJavaAdapter() *JavaAdapter {
	return &JavaAdapter{}
}

// Install installs Java package
func (ja *JavaAdapter) Install(name, version string) error {
	// Maven requires pom.xml modification
	// For now, just provide guidance
	cmd := fmt.Sprintf("mvn dependency:get -Dartifact=%s:%s", name, version)
	if version == "latest" {
		cmd = fmt.Sprintf("mvn dependency:get -Dartifact=%s:RELEASE", name)
	}

	return runCommand(cmd)
}

// Remove removes Java package
func (ja *JavaAdapter) Remove(name string) error {
	// Maven doesn't have direct uninstall; requires pom.xml modification
	return nil
}

// ListInstalled lists installed Java packages
func (ja *JavaAdapter) ListInstalled() ([]Package, error) {
	output, err := exec.Command("mvn", "dependency:tree").CombinedOutput()
	if err != nil {
		return nil, err
	}

	var packages []Package
	lines := strings.Split(string(output), "\n")

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || !strings.Contains(line, ":") {
			continue
		}

		// Parse "groupId:artifactId:version"
		parts := strings.Split(line, ":")
		if len(parts) >= 3 {
			packages = append(packages, Package{
				Name:     fmt.Sprintf("%s:%s", parts[0], parts[1]),
				Version:  parts[2],
				Language: "java",
			})
		}
	}

	return packages, nil
}

// GetVersion gets Java package version
func (ja *JavaAdapter) GetVersion(name string) (string, error) {
	// Query Maven central
	output, err := exec.Command("mvn", "dependency:get", fmt.Sprintf("-Dartifact=%s", name)).CombinedOutput()
	if err != nil {
		return "", err
	}

	// Parse output
	lines := strings.Split(string(output), "\n")
	for _, line := range lines {
		if strings.Contains(line, "Downloaded") || strings.Contains(line, "Version") {
			parts := strings.Fields(line)
			if len(parts) > 0 {
				return parts[len(parts)-1], nil
			}
		}
	}

	return "", fmt.Errorf("could not determine version")
}

// ============================================================================
// Kotlin Adapter (Gradle)
// ============================================================================

// KotlinAdapter adapts Kotlin package manager (Gradle)
type KotlinAdapter struct{}

// NewKotlinAdapter creates Kotlin adapter
func NewKotlinAdapter() *KotlinAdapter {
	return &KotlinAdapter{}
}

// Install installs Kotlin package
func (ka *KotlinAdapter) Install(name, version string) error {
	// Gradle requires build.gradle modification
	cmd := fmt.Sprintf("gradle dependencies --include-build-script --configuration compile")
	return runCommand(cmd)
}

// Remove removes Kotlin package
func (ka *KotlinAdapter) Remove(name string) error {
	// Gradle doesn't have direct uninstall; requires build.gradle modification
	return nil
}

// ListInstalled lists installed Kotlin packages
func (ka *KotlinAdapter) ListInstalled() ([]Package, error) {
	output, err := exec.Command("gradle", "dependencies", "--configuration", "implementation").CombinedOutput()
	if err != nil {
		return nil, err
	}

	var packages []Package
	lines := strings.Split(string(output), "\n")

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || !strings.Contains(line, ":") {
			continue
		}

		// Parse "groupId:artifactId:version"
		parts := strings.Split(line, ":")
		if len(parts) >= 3 {
			packages = append(packages, Package{
				Name:     fmt.Sprintf("%s:%s", parts[0], parts[1]),
				Version:  parts[2],
				Language: "kotlin",
			})
		}
	}

	return packages, nil
}

// GetVersion gets Kotlin package version
func (ka *KotlinAdapter) GetVersion(name string) (string, error) {
	output, err := exec.Command("gradle", "dependencies", "--configuration", "implementation").CombinedOutput()
	if err != nil {
		return "", err
	}

	lines := strings.Split(string(output), "\n")
	for _, line := range lines {
		if strings.Contains(line, name) {
			parts := strings.Split(line, ":")
			if len(parts) >= 3 {
				return parts[2], nil
			}
		}
	}

	return "", fmt.Errorf("could not determine version")
}

// ============================================================================
// Helper Functions
// ============================================================================

// runCommand runs shell command
func runCommand(cmd string) error {
	parts := strings.Fields(cmd)
	if len(parts) == 0 {
		return fmt.Errorf("empty command")
	}

	execCmd := exec.Command(parts[0], parts[1:]...)
	output, err := execCmd.CombinedOutput()

	if err != nil {
		return fmt.Errorf("command failed: %s\nOutput: %s", cmd, string(output))
	}

	return nil
}

