	output, err := exec.Command("julia", "-e", fmt.Sprintf("using Pkg; println(Pkg.status(\"%s\"))", name)).CombinedOutput()
	if err != nil {
		return "", err
	}

	// Parse output
	lines := strings.Split(string(output), "\n")
	for _, line := range lines {
		parts := strings.Fields(line)
		if len(parts) >= 2 {
			return parts[1], nil
		}
	}

	return "", fmt.Errorf("could not determine version")
}

// ============================================================================
// Helper Functions
