	@[ -f bin/string_ops_py ] && (echo "Python (Cython):"; bin/string_ops_py 2>&1 | head -3) || echo "❌ String ops binary not found"
	@echo ""
	@echo "Phase 5: Calculator"
	@echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
	@[ -f bin/calculator_py ] && (echo "Python (Cython):"; bin/calculator_py 2>&1 | head -5) || echo "❌ Calculator binary not found"

# 정리
clean-c:
	@echo "🧹 Cleaning C build artifacts..."
	@rm -rf $(BUILD_DIR) $(BIN_DIR)
