# ============================================================================
# Phase K.1b: C-Centric 통합 빌드 시스템
# ============================================================================

# 디렉토리 생성
$(BUILD_DIR):
	mkdir -p $(BUILD_DIR)

$(BIN_DIR):
	mkdir -p $(BIN_DIR)

# Step 1: FreeLang → C 변환
freelang-to-c: $(BUILD_DIR)
	@echo "🔨 Converting FreeLang to C..."
	@echo ""
	@for phase in $(PHASES); do \
		for fl_file in $(KERNELS_DIR)/$$phase/*.fl; do \
			[ -f "$$fl_file" ] || continue; \
			base=$$(basename $$fl_file .fl); \
			echo "  → $$phase/$$base.fl → C"; \
			$(FREELANG_CC) $$fl_file -o $(BUILD_DIR)/$${base}_fl.c 2>/dev/null || echo "    ⚠️  Skipped"; \
		done; \
	done
	@echo ""
	@echo "✅ FreeLang → C conversion complete"

# Step 2: Python → C (Cython)
python-to-c: $(BUILD_DIR)
	@echo "🔨 Converting Python to C (Cython)..."
	@echo ""
	@for phase in $(PHASES); do \
		for py_file in $(KERNELS_DIR)/$$phase/*.py; do \
			[ -f "$$py_file" ] || continue; \
			base=$$(basename $$py_file .py); \
			echo "  → $$phase/$$base.py → C"; \
			cython --embed "$$py_file" -o $(BUILD_DIR)/$${base}_py.c 2>/dev/null || echo "    ⚠️  Cython not available"; \
		done; \
	done
	@echo ""
	@echo "✅ Python → C conversion complete (if Cython available)"

# Step 3: C 코드 컴파일
c-compile: $(BIN_DIR)
	@echo "🔨 Compiling C code with GCC..."
	@echo ""
	@for c_file in $(BUILD_DIR)/*.c; do \
		[ -f "$$c_file" ] || continue; \
		base=$$(basename $$c_file .c); \
		echo "  → $$base.c → bin/$$base"; \
		$(CC) $(CFLAGS) "$$c_file" -o $(BIN_DIR)/$$base $(LDFLAGS) 2>/dev/null && echo "    ✓ Success" || echo "    ✗ Failed"; \
	done
	@echo ""
	@echo "✅ C compilation complete"

# 통합: 모든 언어 → C → 바이너리
build-all-c: clean freelang-to-c python-to-c c-compile
	@echo ""
