	@echo "🧪 Testing all compiled binaries..."
	@echo ""
	@for binary in $(BIN_DIR)/*; do \
		[ -x "$$binary" ] || continue; \
		name=$$(basename $$binary); \
		echo "  ▶ $$name"; \
		"$$binary" 2>&1 | head -5; \
		echo ""; \
	done
	@echo "✅ Test complete"

# Benchmark: 성능 비교
