# ============================================================================
# Phase K.1b: C-Centric 통합 빌드 시스템
# ============================================================================

# Python 설정
PYTHON_INCLUDES := $(shell python3-config --includes)
PYTHON_LIBS := $(shell python3-config --libs)

# 디렉토리 생성
$(BUILD_DIR):
	mkdir -p $(BUILD_DIR)

$(BIN_DIR):
	mkdir -p $(BIN_DIR)

# Step 1: Python → C (Cython 변환)
python-to-c: $(BUILD_DIR)
	@echo "🔨 Converting Python to C (Cython)..."
	@echo ""
	@count=0; \
	for phase in $(PHASES); do \
		for py_file in $(KERNELS_DIR)/$$phase/*.py; do \
			[ -f "$$py_file" ] || continue; \
			count=$$((count + 1)); \
			base=$$(basename $$py_file .py); \
			echo "  → $$phase/$$base.py"; \
			cython --embed "$$py_file" -o $(BUILD_DIR)/$${base}_py.c 2>/dev/null && echo "    ✓ C 생성" || echo "    ✗ 실패"; \
		done; \
	done; \
	echo ""; \
	[ $$count -gt 0 ] && echo "✅ $$count개 Python 파일 변환 완료" || echo "⚠️  Python 파일 없음"

# Step 2: Python C 코드 컴파일
python-compile: $(BIN_DIR)
	@echo "🔨 Compiling Python→C binaries..."
	@echo ""
	@count=0; \
	for c_file in $(BUILD_DIR)/*_py.c; do \
		[ -f "$$c_file" ] || continue; \
		count=$$((count + 1)); \
		base=$$(basename $$c_file _py.c); \
		echo "  → $$base (Python C)"; \
		$(CC) $(CFLAGS) "$$c_file" -o $(BIN_DIR)/$${base}_py $(PYTHON_INCLUDES) $(PYTHON_LIBS) 2>/dev/null && echo "    ✓ 컴파일" || echo "    ✗ 실패"; \
	done; \
	echo ""; \
	[ $$count -gt 0 ] && echo "✅ $$count개 Python C 바이너리 생성" || echo "⚠️  컴파일 대상 없음"

# Step 3: 기존 C 파일 컴파일 (참고용)
c-existing: $(BIN_DIR)
	@echo "🔨 Compiling existing C files..."
	@echo ""
	@count=0; \
	for phase in $(PHASES); do \
		for c_file in $(KERNELS_DIR)/$$phase/*.c; do \
			[ -f "$$c_file" ] || continue; \
			count=$$((count + 1)); \
			base=$$(basename $$c_file .c); \
			echo "  → $$phase/$$base.c"; \
			$(CC) $(CFLAGS) "$$c_file" -o $(BIN_DIR)/$${base}_c $(LDFLAGS) 2>/dev/null && echo "    ✓ 컴파일" || echo "    ✗ 실패"; \
		done; \
	done; \
	echo ""; \
	[ $$count -gt 0 ] && echo "✅ $$count개 C 바이너리 생성" || echo "⚠️  C 파일 없음"

# 통합: Python + C → 바이너리
build-all-c: clean python-to-c python-compile c-existing
	@echo ""
	@echo "╔════════════════════════════════════════════════════════════════╗"
	@echo "║               ✅ C-CENTRIC BUILD COMPLETE                      ║"
	@echo "║                                                                ║"
	@echo "║  Python → Cython → C → gcc 컴파일 성공                        ║"
	@echo "║  네이티브 바이너리 생성: bin/                                  ║"
	@echo "╚════════════════════════════════════════════════════════════════╝"

# Test: 모든 바이너리 실행
test-all-c: build-all-c
	@echo ""
	@echo "🧪 Testing C-compiled binaries..."
	@echo ""
	@[ -d $(BIN_DIR) ] && find $(BIN_DIR) -type f -executable | while read binary; do \
		name=$$(basename $$binary); \
		echo "▶ $$name"; \
		$$binary 2>&1 | head -3; \
		echo ""; \
	done || echo "⚠️  No binaries found"
