toolUseResult.originalFile:
# ============================================================================
# Polyglot PoC - Makefile
# ============================================================================
# 개발, 빌드, 테스트, 배포 자동화
# ============================================================================

.PHONY: help build test clean install docker docker-up docker-down lint format \
         build-all-c test-all-c benchmark-c freelang-to-c python-to-c c-compile

# ============================================================================
# 기본 설정
# ============================================================================

PROJECT_NAME := polyglot-poc
DOCKER_IMAGE := $(PROJECT_NAME):latest
DOCKER_CONTAINER := $(PROJECT_NAME)-dev

SHELL := /bin/bash
.DEFAULT_GOAL := help

# ============================================================================
# 변수
# ============================================================================

GO_VERSION := 1.21.0
PHASES := 01_hello_world 02_fibonacci 03_string_ops 04_array_ops 05_calculator
KERNELS_DIR := kernels
VALIDATION_DIR := validation
REPORTS_DIR := reports
LANGUAGES := go c freelang wasm fv-julia python rust typescript java kotlin
BUILD_DIR := build
BIN_DIR := bin

# C-Centric Tools
FREELANG_CC := /data/data/com.termux/files/home/projects/freelang-to-c/bin/freelang-to-c
CC := gcc
CFLAGS := -O2 -Wall -Wextra -std=c99
LDFLAGS := -lm

# ============================================================================
# 헬프 (기본)
# ============================================================================

help:
	@echo "╔════════════════════════════════════════════════════════════════╗"
	@echo "║          Polyglot PoC - Development & Build System            ║"
	@echo "╚════════════════════════════════════════════════════════════════╝"
	@echo ""
	@echo "📚 CORE TARGETS:"
	@echo "  make help          - Show this help message"
	@echo "  make build         - Build all examples (Go + C)"
	@echo "  make test          - Run all tests (Phase 1-5)"
	@echo "  make clean         - Clean all build artifacts"
	@echo ""
	@echo "🐳 DOCKER TARGETS:"
	@echo "  make docker        - Build Docker image"
	@echo "  make docker-up     - Start Docker development environment"
	@echo "  make docker-down   - Stop Docker environment"
	@echo "  make docker-shell  - Open shell in running container"
	@echo ""
	@echo "📖 DOCUMENTATION:"
	@echo "  make docs          - Generate/view documentation"
	@echo "  make quick-start   - Show QUICK_START.md"
	@echo ""
	@echo "🔧 CODE QUALITY:"
	@echo "  make lint          - Lint all code"
	@echo "  make format        - Format all code"
	@echo ""
	@echo "📊 ANALYSIS:"
	@echo "  make stats         - Show code statistics"
	@echo "  make coverage      - Show test coverage"
	@echo ""
	@echo "🚀 ADVANCED:"
	@echo "  make install-deps  - Install all dependencies"
	@echo "  make validate-all  - Full validation (build + test + lint)"
	@echo ""

# ============================================================================
# 빌드 대상
# ============================================================================

build: build-go build-c
	@echo "✅ Build complete!"

build-go:
	@echo "🔨 Building Go examples..."
	@for phase in $(PHASES); do \
		echo "  → Compiling $$phase (Go)..."; \
		(cd $(KERNELS_DIR)/$$phase && go build -o /tmp/$$phase *.go 2>/dev/null && echo "    ✓ Success") || echo "    ✗ Skipped"; \
	done

build-c:
	@echo "🔨 Building C examples..."
	@for phase in $(PHASES); do \
		echo "  → Compiling $$phase (C)..."; \
		(cd $(KERNELS_DIR)/$$phase && gcc -lm -o /tmp/$$phase-c *.c 2>/dev/null && echo "    ✓ Success") || echo "    ✗ Skipped"; \
	done

build-python:
	@echo "🔨 Building Python examples..."
	@for phase in $(PHASES); do \
		if [ -d $(KERNELS_DIR)/$$phase ]; then \
			for file in $(KERNELS_DIR)/$$phase/*.py; do \
				[ -f "$$file" ] && echo "  → Checking $$file..." && python3 -m py_compile "$$file" 2>/dev/null && echo "    ✓ Syntax OK" || echo "    ✗ Skipped"; \
			done; \
		fi; \
	done

build-rust:
	@echo "🔨 Building Rust examples..."
	@for phase in $(PHASES); do \
		if [ -d $(KERNELS_DIR)/$$phase ]; then \
			for file in $(KERNELS_DIR)/$$phase/*.rs; do \
				[ -f "$$file" ] && echo "  → Checking $$file..." && rustc --crate-type bin -o /tmp/$$(basename $$file .rs) "$$file" 2>/dev/null && echo "    ✓ Compiled" || echo "    ✗ Skipped"; \
			done; \
		fi; \
	done

build-typescript:
	@echo "🔨 Building TypeScript examples..."
	@for phase in $(PHASES); do \
		if [ -d $(KERNELS_DIR)/$$phase ]; then \
			for file in $(KERNELS_DIR)/$$phase/*.ts; do \
				[ -f "$$file" ] && echo "  → Checking $$file..." && tsc --noEmit "$$file" 2>/dev/null && echo "    ✓ Type check OK" || echo "    ✗ Skipped"; \
			done; \
		fi; \
	done

build-java:
	@echo "🔨 Building Java examples..."
	@for phase in $(PHASES); do \
		if [ -d $(KERNELS_DIR)/$$phase ]; then \
			for file in $(KERNELS_DIR)/$$phase/*.java; do \
				[ -f "$$file" ] && echo "  → Compiling $$file..." && javac "$$file" 2>/dev/null && echo "    ✓ Compiled" || echo "    ✗ Skipped"; \
			done; \
		fi; \
	done

build-kotlin:
	@echo "🔨 Building Kotlin examples..."
	@for phase in $(PHASES); do \
		if [ -d $(KERNELS_DIR)/$$phase ]; then \
			for file in $(KERNELS_DIR)/$$phase/*.kt; do \
				[ -f "$$file" ] && echo "  → Compiling $$file..." && kotlinc "$$file" -include-runtime -d /tmp/$$(basename $$file .kt).jar 2>/dev/null && echo "    ✓ Compiled" || echo "    ✗ Skipped"; \
			done; \
		fi; \
	done

# ============================================================================
# 테스트 대상
# ============================================================================

test: test-go
	@echo "✅ All tests passed!"

test-go:
	@echo "🧪 Running Go tests..."
	@echo ""
	@for phase in $(PHASES); do \
		echo "📍 Phase: $$phase"; \
		(cd $(KERNELS_DIR)/$$phase && go run *.go 2>&1) || echo "Test failed"; \
		echo ""; \
	done
	@echo "✅ Test summary:"
	@echo "  Phase 1: Hello World (10 languages)"
	@echo "  Phase 2: Fibonacci (recursive, iterative, memoized)"
	@echo "  Phase 3: String Operations (15+ functions)"
	@echo "  Phase 4: Array Operations (map, filter, fold)"
	@echo "  Phase 5: Calculator (6 operations + history)"

test-c:
	@echo "🧪 Running C tests..."
	@for phase in $(PHASES); do \
		if [ -f $(KERNELS_DIR)/$$phase/*.c ]; then \
			echo "  → Testing $$phase (C)..."; \
			(cd $(KERNELS_DIR)/$$phase && gcc -lm -o /tmp/test *.c && /tmp/test) || echo "Test failed"; \
		fi; \
	done

test-all: test test-c
	@echo "✅ All language tests completed!"

# ============================================================================
# 정리
# ============================================================================

clean:
	@echo "🧹 Cleaning build artifacts..."
	@find . -name "*.o" -delete
	@find . -name "*.a" -delete
	@find . -name "*.so" -delete
	@find /tmp -name "$(PROJECT_NAME)*" -delete 2>/dev/null || true
	@rm -rf .build 2>/dev/null || true
	@echo "✅ Clean complete!"

# ============================================================================
# Docker 대상
# ============================================================================

docker:
	@echo "🐳 Building Docker image..."
	@docker build -t $(DOCKER_IMAGE) docker/
	@echo "✅ Docker image built: $(DOCKER_IMAGE)"

docker-up:
	@echo "🐳 Starting Docker environment..."
	@docker-compose -f docker/docker-compose.yml up -d
	@echo "✅ Environment started!"
	@echo ""
	@echo "📝 Next steps:"
	@echo "  docker-compose -f docker/docker-compose.yml exec polyglot-dev bash"
	@echo "  cd /workspace && make test"

docker-down:
	@echo "🐳 Stopping Docker environment..."
	@docker-compose -f docker/docker-compose.yml down
	@echo "✅ Environment stopped!"

docker-shell:
	@echo "🐳 Opening shell in container..."
	@docker-compose -f docker/docker-compose.yml exec polyglot-dev bash

docker-logs:
	@docker-compose -f docker/docker-compose.yml logs -f polyglot-dev

# ============================================================================
# 문서
# ============================================================================

docs:
	@echo "📖 Available documentation:"
	@echo ""
	@echo "Quick Start:"
	@cat guides/QUICK_START.md | head -30
	@echo ""
	@echo "For full documentation, see:"
	@echo "  - guides/QUICK_START.md"
	@echo "  - guides/INSTALLATION.md"
	@echo "  - docs/API.md"
	@echo "  - reports/PHASE_*.md"

quick-start:
	@cat guides/QUICK_START.md

# ============================================================================
# 코드 품질
# ============================================================================

lint:
	@echo "🔍 Linting Go code..."
	@command -v golangci-lint >/dev/null 2>&1 && \
		for phase in $(PHASES); do \
			echo "  → Linting $$phase..."; \
			(cd $(KERNELS_DIR)/$$phase && golangci-lint run ./... 2>/dev/null) || echo "    Skipped (golangci-lint not installed)"; \
		done || echo "  ⚠️  golangci-lint not installed. Install with: go install github.com/golangci/golangci-lint/cmd/golangci-lint@latest"

format:
	@echo "✨ Formatting Go code..."
	@for phase in $(PHASES); do \
		echo "  → Formatting $$phase..."; \
		(cd $(KERNELS_DIR)/$$phase && gofmt -w . && echo "    ✓ Formatted") || echo "    ✗ Failed"; \
	done

# ============================================================================
# 통계 및 분석
# ============================================================================

stats:
	@echo "📊 Code Statistics"
	@echo ""
	@echo "Python Files:"
	@find $(KERNELS_DIR) -name "*.py" | xargs wc -l | tail -1 2>/dev/null || echo "  0 lines"
	@echo ""
	@echo "Rust Files:"
	@find $(KERNELS_DIR) -name "*.rs" | xargs wc -l | tail -1 2>/dev/null || echo "  0 lines"
	@echo ""
	@echo "TypeScript Files:"
	@find $(KERNELS_DIR) -name "*.ts" | xargs wc -l | tail -1 2>/dev/null || echo "  0 lines"
	@echo ""
	@echo "Java Files:"
	@find $(KERNELS_DIR) -name "*.java" | xargs wc -l | tail -1 2>/dev/null || echo "  0 lines"
	@echo ""
	@echo "Kotlin Files:"
	@find $(KERNELS_DIR) -name "*.kt" | xargs wc -l | tail -1 2>/dev/null || echo "  0 lines"
	@echo ""
	@echo "All Language Files:"
	@find $(KERNELS_DIR) -type f \( -name "*.py" -o -name "*.rs" -o -name "*.ts" -o -name "*.java" -o -name "*.kt" -o -name "*.go" \) | xargs wc -l | tail -1 2>/dev/null || echo "  0 lines"
	@echo ""
	@echo "Documentation:"
	@find guides docs -name "*.md" | xargs wc -l | tail -1 2>/dev/null || echo "  0 lines"

coverage:
	@echo "📈 Language Coverage"
	@echo ""
	@echo "Phase 1 (Hello World):"
	@echo "  ✅ Go        ✅ C       ✅ FreeLang  ✅ WASM     ✅ FV-Julia"
	@echo "  ✅ Python    ✅ Rust    ✅ TypeScript ✅ Java    ✅ Kotlin"
	@echo ""
	@echo "Phase 2 (Fibonacci):"
	@for phase in $(PHASES); do \
		if [ "$$phase" = "02_fibonacci" ]; then \
			echo "  ✅ Python    ✅ Rust    ✅ TypeScript ✅ Java    ✅ Kotlin"; \
		fi; \
	done
	@echo ""
	@echo "Overall: 10 Languages × 5 Phases = 50 Kernel Files"

# ============================================================================
# 설치 및 검증
# ============================================================================

