// Fibonacci - Rust Implementation
// Phase 2: Recursion, Iteration, Memoization

use std::time::Instant;
use std::collections::HashMap;

fn fib_recursive(n: u32) -> u32 {
    if n <= 1 {
        return n;
    }
    fib_recursive(n - 1) + fib_recursive(n - 2)
}

fn fib_iterative(n: u32) -> u32 {
    if n <= 1 {
        return n;
    }

    let mut a = 0u32;
    let mut b = 1u32;

    for _ in 2..=n {
        let temp = a + b;
        a = b;
        b = temp;
    }

    b
}

fn fib_memoized(n: u32, memo: &mut HashMap<u32, u32>) -> u32 {
    if let Some(&result) = memo.get(&n) {
        return result;
    }

    let result = if n <= 1 {
        n
    } else {
        fib_memoized(n - 1, memo) + fib_memoized(n - 2, memo)
    };

    memo.insert(n, result);
    result
}

fn main() {
    let n = 10;

    // Recursive
    let start = Instant::now();
    let result_recursive = fib_recursive(n);
    let time_recursive = start.elapsed().as_secs_f64() * 1000.0;

    // Iterative
    let start = Instant::now();
    let result_iterative = fib_iterative(n);
    let time_iterative = start.elapsed().as_secs_f64() * 1000.0;

    // Memoized
    let start = Instant::now();
    let mut memo = HashMap::new();
    let result_memoized = fib_memoized(n, &mut memo);
    let time_memoized = start.elapsed().as_secs_f64() * 1000.0;

    println!("fib({}) = {} (recursive: {:.3}ms)", n, result_recursive, time_recursive);
    println!("fib({}) = {} (iterative: {:.3}ms)", n, result_iterative, time_iterative);
    println!("fib({}) = {} (memoized: {:.3}ms)", n, result_memoized, time_memoized);
}

// Fibonacci - Go Version
//
// 목표: FV 2.0 (Go) 컴파일러의 Go 코드 생성 검증
// 특징: Go의 강점인 고루틴, 채널 제외 (단순 재귀 + 동적 계획법)

package main

import "fmt"

// 기본 재귀 버전 (성능은 낮지만 로직 검증용)
func fib(n int64) int64 {
	if n <= 1 {
		return n
	}
	return fib(n-1) + fib(n-2)
}

// 최적화 버전: 동적 계획법 (메모이제이션)
// 캐시를 사용하여 중복 계산 제거
func fibMemo(n int64, memo map[int64]int64) int64 {
	if n <= 1 {
		return n
	}

	if val, exists := memo[n]; exists {
		return val
	}

	result := fibMemo(n-1, memo) + fibMemo(n-2, memo)
	memo[n] = result
	return result
}

// 반복문 버전 (가장 효율적)
func fibIterative(n int64) int64 {
	if n <= 1 {
		return n
	}

	a, b := int64(0), int64(1)
	for i := int64(2); i <= n; i++ {
		a, b = b, a+b
	}
	return b
}

// 테스트 함수
func testFibonacci() bool {
	tests := map[int64]int64{
		0:  0,
		1:  1,
		2:  1,
		3:  2,
		5:  5,
		10: 55,
	}

	for n, expected := range tests {
		result := fib(n)
		if result != expected {
			fmt.Printf("FAIL: fib(%d) = %d, expected %d\n", n, result, expected)
			return false
		}
	}
	return true
}

func main() {
	fmt.Println("╔════════════════════════════════════════════╗")
	fmt.Println("║      Fibonacci Test - Go Version          ║")
	fmt.Println("╚════════════════════════════════════════════╝")
	fmt.Println("")

	fmt.Println("Testing fib() function (재귀):")
	fmt.Printf("  fib(0) = %d\n", fib(0))
	fmt.Printf("  fib(1) = %d\n", fib(1))
	fmt.Printf("  fib(2) = %d\n", fib(2))
	fmt.Printf("  fib(3) = %d\n", fib(3))
	fmt.Printf("  fib(5) = %d\n", fib(5))
	fmt.Printf("  fib(10) = %d\n", fib(10))
	fmt.Println("")

	fmt.Println("Testing fibIterative() function (반복):")
	fmt.Printf("  fibIterative(0) = %d\n", fibIterative(0))
	fmt.Printf("  fibIterative(1) = %d\n", fibIterative(1))
	fmt.Printf("  fibIterative(10) = %d\n", fibIterative(10))
	fmt.Printf("  fibIterative(20) = %d\n", fibIterative(20))
	fmt.Println("")

	fmt.Println("Testing fibMemo() function (메모이제이션):")
	memo := make(map[int64]int64)
	fmt.Printf("  fibMemo(10) = %d\n", fibMemo(10, memo))
	memo = make(map[int64]int64)
	fmt.Printf("  fibMemo(20) = %d\n", fibMemo(20, memo))
	fmt.Println("")

	if testFibonacci() {
		fmt.Println("✅ ALL FIBONACCI TESTS PASSED")
	} else {
		fmt.Println("❌ SOME FIBONACCI TESTS FAILED")
	}
}
